scripts.script:
if (args.isBroken) {
    const fushen = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fushen"));
    fushen.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, fushen);
    actor.showFloatyText("缚身！", { fill: "#ff0000" });
}

if (!Macros.checkStance(actor, args) || !args.attacker) return;

const t1 = actor.token?.object || actor.getActiveTokens()[0];
const t2 = args.attacker.token?.object || args.attacker.getActiveTokens()[0];
let inRange = false;

if (t1 && t2) {
    const measure = canvas.grid.measurePath([t1.center, t2.center]);
    if (measure.distance <= 1.1) inRange = true;
}

if (inRange) {
    const root = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    root.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.attacker, root);
    actor.showFloatyText("蛇身缠绕！", { fill: "#FFA500" });
}

if (args.isHit) {
    const pain = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "pain"));
    pain.duration = { rounds: 3 };
    await game.xjzl.api.effects.addEffect(args.target, pain);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const msg = `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #8b0000; background:rgba(139,0,0,0.05); margin-left:4px;">
        <div style="font-weight:bold; color:#8b0000;"><i class="fas fa-wind"></i> 击退触发</div>
        <div style="font-size:0.9em; color:#555; margin-top:2px;">钩穿手臂，用力甩飞。<br>请将 <b>${args.target.name}</b> 朝任意方向移动 <b>1米</b>。</div>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (args.isHit) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);
}

if (args.isHit && args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "prone")) {
    const root = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    root.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, root);

    const pain = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "pain"));
    pain.duration = { rounds: 5 };
    await game.xjzl.api.effects.addEffect(args.target, pain);

    actor.showFloatyText("双钩重创！", { fill: "#ff0000" });
}

if (Macros.checkStance(actor, args)) {
    const effect = thisItem.effects.getName("寻踪");
    if (effect) await game.xjzl.api.effects.addEffect(actor, effect.toObject());
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const panshi = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "panshi"));
    panshi.flags["xjzl-system"].maxStacks = 3;
    await game.xjzl.api.effects.addEffect(actor, panshi);
}

if (args.isHit) {
    const effect = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "chizhi"));
    effect.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, effect);
}

if (args.target && args.target.type === 'creature') {
    args.output.bonusDesc.push("对野兽额外造成 1 点体力伤害。");
}

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_hualong")) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const baseBlock = (args.move.calculation.base || 0) + (args.move.calculation.growth || 0) * (lvl - 1);
    actor.system.combat.block += baseBlock;
}

if (!Macros.checkStance(actor, args)) return;
const bushiTpl = thisItem.effects.getName("捕食");
const hualongTpl = thisItem.effects.getName("化龙");
if (bushiTpl) {
    const effect = await game.xjzl.api.effects.addEffect(actor, bushiTpl.toObject());
    if (effect && (effect.getFlag("xjzl-system", "stacks") || 1) >= 3 && hualongTpl) {
        if (!actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_hualong")) {
            await game.xjzl.api.effects.addEffect(actor, hualongTpl.toObject());
            actor.showFloatyText("化龙！", { fill: "#FFD700", fontSize: 40 });
        }
    }
}

const bushi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_bushi");
const stacks = bushi ? (bushi.getFlag("xjzl-system", "stacks") || 1) : 0;
if (stacks > 0) {
    args.output.damage += stacks * 5;
    args.output.bonusDesc.push(`捕食加成 +${stacks * 5}`);
}
if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_hualong")) {
    args.output.damage += 10;
    args.output.bonusDesc.push("化龙加成 +10");
}

if (!args.isHit) return;
const bushiTpl = thisItem.effects.getName("捕食");
const hualongTpl = thisItem.effects.getName("化龙");
if (bushiTpl) {
    const effect = await game.xjzl.api.effects.addEffect(actor, bushiTpl.toObject());
    // 检查是否叠满3层且尚未获得化龙
    if (effect && (effect.getFlag("xjzl-system", "stacks") || 1) >= 3 && hualongTpl) {
        if (!actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_hualong")) {
            await game.xjzl.api.effects.addEffect(actor, hualongTpl.toObject());
            actor.showFloatyText("化龙！", { fill: "#FFD700", fontSize: 40 });
        }
    }
}

const bushi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_bushi");
const stacks = bushi ? (bushi.getFlag("xjzl-system", "stacks") || 1) : 0;
if (stacks > 0) {
    args.output.damage += stacks * 5;
    args.output.bonusDesc.push(`捕食加成 +${stacks * 5}`);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const effect = thisItem.effects.getName("阻脉");
    if (effect) await game.xjzl.api.effects.addEffect(args.target, effect.toObject());
}

const bushi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_bushi");
const stacks = bushi ? (bushi.getFlag("xjzl-system", "stacks") || 1) : 0;
if (stacks > 0) {
    args.output.damage += stacks * 5;
    args.output.bonusDesc.push(`捕食加成 +${stacks * 5}`);
}

if (args.isHit && actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_hualong")) {
    await game.xjzl.api.effects.addEffect(args.target, "prone");
}

const bushi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_bushi");
const stacks = bushi ? (bushi.getFlag("xjzl-system", "stacks") || 1) : 0;
if (stacks > 0) {
    args.output.damage += stacks * 5;
    args.output.bonusDesc.push(`捕食加成 +${stacks * 5}`);
}

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_hualong")) {
    const effect = thisItem.effects.getName("兽王降世");
    if (effect) await game.xjzl.api.effects.addEffect(actor, effect.toObject());
}

if (args.isBroken) {
    const effect = thisItem.effects.getName("飞禽");
    if (effect) await game.xjzl.api.effects.addEffect(actor, effect.toObject());
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const rounds = 1 + (lvl - 1);
const effectData = thisItem.effects.getName("走兽").toObject();
effectData.duration = { rounds: rounds };
await game.xjzl.api.effects.addEffect(actor, effectData);

const hasBird = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_bird");
const hasBeast = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_beast");
const hasFish = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_wanshou_fish");

if (hasBird) {
    const bird = thisItem.effects.getName("飞禽");
    if (bird) await game.xjzl.api.effects.addEffect(args.target, bird.toObject());
}
if (hasBeast) {
    const beast = thisItem.effects.getName("走兽");
    if (beast) await game.xjzl.api.effects.addEffect(args.target, beast.toObject());
}
if (hasFish) {
    const fish = thisItem.effects.getName("游鱼");
    if (fish) await game.xjzl.api.effects.addEffect(args.target, fish.toObject());
}

if (hasBird && hasBeast && hasFish) {
    const baishou = thisItem.effects.getName("百兽");
    if (baishou) await game.xjzl.api.effects.addEffect(args.target, baishou.toObject());
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const bonus = 1 + (lvl - 1);
if (actor.system.arts.yushou) {
    actor.system.arts.yushou.checkMod = (actor.system.arts.yushou.checkMod || 0) + bonus;
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const bonus = 10 + (lvl - 1) * 5;
const effectData = thisItem.effects.getName("野性").toObject();
effectData.description = `防护+${bonus}，伤害+${bonus}。结束时体力上限-1。`;
effectData.changes = [
    { key: "system.combat.protection", mode: 2, value: bonus },
    { key: "system.combat.damages.global.mod", mode: 2, value: bonus }
];
await game.xjzl.api.effects.addEffect(args.target, effectData);

const wuxue = actor.itemTypes.wuxue.find(w => w.name === "兽窍五通");
const lvl = wuxue ? (wuxue.system.moves.find(m => m.name === "兽窍五通")?.computedLevel || 0) : 0;
if (lvl <= 0) return;
const bonus = 2 + lvl;
S.stats.liliang.checkMod += bonus;
S.skills.jiaoli.checkMod += bonus;
S.skills.zhengtuo.checkMod += bonus;
S.skills.paozhi.checkMod += bonus;
S.skills.qinbao.checkMod += bonus;

