S.stats.shenfa.checkMod += bonus;
S.skills.qianxing.checkMod += bonus;
S.skills.qiaoshou.checkMod += bonus;
S.skills.qinggong.checkMod += bonus;
S.skills.mashu.checkMod += bonus;

